const FSM_N_DUALRESPONSE_ROOT_LEFT: usize = fsm_arena_n(::core::mem::size_of::<ak_dfix_Pair>());
const FSM_N_DUALRESPONSE_ROOT_RIGHT: usize = fsm_arena_n(::core::mem::size_of::<ak_dfix_Pair>());
/// `DualResponse`'s root group, in words; then the largest non-leaf element group.
const FSM_ROOT_WORDS_DUALRESPONSE: usize = ::core::mem::size_of::<ak_dfix_DualResponse>().div_ceil(8);
const FSM_ELEM_WORDS_DUALRESPONSE: usize = 0;
/// Frames `DualResponse` can open at once: 1 (refused above FSM_MAX_FRAMES).
const _: () = assert!(1 <= FSM_MAX_FRAMES);

/// `DualResponse`'s state machine: advance from the context's state to the next event.
/// Frames: 0 root DualResponse.
#[allow(unused_variables, unused_mut, unused_macros, unreachable_code, unused_unsafe)]
unsafe fn fsm_step_dual_response(dcx: *mut DecCtxImpl, f: &mut FsmCx, ev: *mut ak_fsm_ev) -> i32 {
    let buf: &[u8] = f.input();
    let gr = f.grp.as_mut_ptr() as *mut ak_dfix_DualResponse;
    let ar = f.arena.as_mut_ptr();
    let u0 = FsmU::root(dcx);
    let sk = f.sk;
    macro_rules! fail {
        ($e:expr) => {{
            let e = $e;
            f.state = ST_FAILED;
            return e;
        }};
    }
    macro_rules! ev_run_root {
        () => {{
            match f.cur {
                1 => ev.write(ak_fsm_ev { op: AK_BDR_ADD, slot: 1, token: AK_TOKEN_ROOT, n: f.n as u32, bytes: (f.n * ::core::mem::size_of::<ak_dfix_Pair>()) as u32, data: ar as *const c_void }),
                2 => ev.write(ak_fsm_ev { op: AK_BDR_ADD, slot: 2, token: AK_TOKEN_ROOT, n: f.n as u32, bytes: (f.n * ::core::mem::size_of::<ak_dfix_Pair>()) as u32, data: ar as *const c_void }),
                _ => fail!(AK_ERR_ABI),
            }
            f.n = 0;
        }};
    }
    macro_rules! pre_other_root {
        ($s0:ident) => {
            if f.cur != 0 {
                if f.n > 0 { ev_run_root!(); f.cur = 0; f.pos = $s0; return AK_OK; }
                f.cur = 0;
            }
        };
    }
    macro_rules! pre_slot_nocap_root {
        ($s0:ident, $sid:expr) => {
            if f.cur != $sid {
                if f.n > 0 { ev_run_root!(); f.cur = 0; f.pos = $s0; return AK_OK; }
                f.cur = $sid;
            }
        };
    }
    macro_rules! pre_slot_root {
        ($s0:ident, $sid:expr, $cap:expr) => {
            pre_slot_nocap_root!($s0, $sid);
            if f.n == $cap { ev_run_root!(); f.pos = $s0; return AK_OK; }
        };
    }
    // An error owed since a truncated non-leaf element falls due once its frame closed.
    if f.pend != 0 && f.depth <= f.pend_depth { fail!(f.pend); }
    loop {
        let top = f.frames[f.depth - 1];
        if f.pos >= top.end {
            // The open message ends here.
            match top.kind {
                0 => {
                    if f.n > 0 { ev_run_root!(); return AK_OK; }
                    ev.write(ak_fsm_ev { op: AK_BDR_APPLY, slot: 0, token: AK_TOKEN_ROOT, n: 1,
                        bytes: ::core::mem::size_of::<ak_dfix_DualResponse>() as u32, data: gr as *const c_void });
                    f.state = ST_DONE;
                    return AK_FSM_END;
                }
                _ => {
                    f.depth -= 1;
                    continue;
                }
            }
        }
        let mut r = FRd { buf, pos: f.pos, end: top.end, err: 0 };
        let s0 = r.pos;
        let k = r.varint();
        if r.err != 0 { fail!(r.err); }
        let (tag, wire) = ((k >> 3) as u32, (k & 7) as u32);
        if tag == 0 || (k >> 3) > FSM_MAX_FIELD_NUMBER { fail!(AK_ERR_MALFORMED); }
        match top.kind {
            0 => match tag {
                1 if wire == 2 => {
                    pre_slot_root!(s0, 1, FSM_N_DUALRESPONSE_ROOT_LEFT);
                    let (off, n) = r.len_body();
                    if r.err != 0 { fail!(r.err); }
                    let e = (ar as *mut ak_dfix_Pair).add(f.n);
                    e.write(ak_dfix_Pair::ZERO);
                    let mut es = r.sub(off, n);
                    fsm_pair_fix_into(&mut es, u0.at(1), sk, &mut *e);
                    if es.err != 0 { fail!(es.err); }
                    f.n += 1;
                }
                2 if wire == 2 => {
                    pre_slot_root!(s0, 2, FSM_N_DUALRESPONSE_ROOT_RIGHT);
                    let (off, n) = r.len_body();
                    if r.err != 0 { fail!(r.err); }
                    let e = (ar as *mut ak_dfix_Pair).add(f.n);
                    e.write(ak_dfix_Pair::ZERO);
                    let mut es = r.sub(off, n);
                    fsm_pair_fix_into(&mut es, u0.at(2), sk >> 1, &mut *e);
                    if es.err != 0 { fail!(es.err); }
                    f.n += 1;
                }
                _ => {
                    pre_other_root!(s0);
                    r.skip(tag, wire);
                    if r.err != 0 { fail!(r.err); }
                    if !u0.pos.is_null() {
                        let rc = fsm_unk_put(u0.at(0), &mut (*gr).unknown, &buf[s0..r.pos]);
                        if rc != 0 { fail!(rc); }
                    }
                }
            },
            _ => fail!(AK_ERR_ABI),
        }
        f.pos = r.pos;
    }
}

/// D23: start an FSM decode of `buf` (valid and unmoved until the end event or an error) and write its FIRST event. AK_OK = more follow, AK_FSM_END = this was the root group, < 0 = error.
#[no_mangle]
pub unsafe extern "C" fn ak_fsm_begin_DualResponse(ctx: *mut ak_dec_ctx, buf: *const u8, len: usize, ev: *mut ak_fsm_ev) -> i32 {
    // ABI v1 section 3: every entry point requires `ak_init`.
    #[cfg(feature = "init-guard")]
    if !crate::ak_init_ok() {
        return AK_ERR_UNINITIALIZED;
    }
    if ctx.is_null() || ev.is_null() { return AK_ERR_INVALID_STATE; }
    let dcx = ctx as *mut DecCtxImpl;
    ak_rt::bump!((*dcx).c, forward);
    // A new operation clears the sticky slot (the rule of the other families).
    (*dcx).hdr.err = AK_OK;
    if (*dcx).root != 7 { (*dcx).hdr.err = AK_ERR_INVALID_STATE; return AK_ERR_INVALID_STATE; }
    let f = fsm_of(dcx);
    // R-D9: spans are (u32, u32), so a longer buffer is refused at entry.
    if len > u32::MAX as usize {
        f.state = ST_FAILED;
        (*dcx).hdr.err = AK_ERR_LIMIT;
        return AK_ERR_LIMIT;
    }
    f.start(buf, len, FSM_ROOT_WORDS_DUALRESPONSE + FSM_ELEM_WORDS_DUALRESPONSE);
    f.sk = f.utf8_skip;
    (f.grp.as_mut_ptr() as *mut ak_dfix_DualResponse).write(ak_dfix_DualResponse::ZERO);
    fsm_step_dual_response(dcx, f, ev)
}

/// D23: write the next event; same returns. AK_ERR_INVALID_STATE after the end or an error.
#[no_mangle]
pub unsafe extern "C" fn ak_fsm_next_DualResponse(ctx: *mut ak_dec_ctx, ev: *mut ak_fsm_ev) -> i32 {
    // ABI v1 section 3: every entry point requires `ak_init`.
    #[cfg(feature = "init-guard")]
    if !crate::ak_init_ok() {
        return AK_ERR_UNINITIALIZED;
    }
    if ctx.is_null() || ev.is_null() { return AK_ERR_INVALID_STATE; }
    let dcx = ctx as *mut DecCtxImpl;
    ak_rt::bump!((*dcx).c, forward);
    if (*dcx).root != 7 { return AK_ERR_INVALID_STATE; }
    let f = match (*dcx).fsm.as_deref_mut() {
        Some(f) if f.state == ST_RUN => f,
        // Never begun, ended, or failed: refused.
        _ => return AK_ERR_INVALID_STATE,
    };
    // The host failed the operation between two events (ak_fail): it ends here.
    if (*dcx).hdr.err != AK_OK { f.state = ST_FAILED; return (*dcx).hdr.err; }
    fsm_step_dual_response(dcx, f, ev)
}

